// ── 入口 ────────────────────────────────────────────────
function help() {
  info(`
${C.b('openprototype')} — 本地原型工作台脚手架

用法：
  ${C.g('openprototype create <dir>')}       从零创建新项目
  ${C.g('openprototype init')}               补充缺失资产、合并脚本，并按配置安装常驻服务
