  '.jpeg': 'image/jpeg',
  '.svg': 'image/svg+xml',
  '.ico': 'image/x-icon',
  '.woff': 'font/woff',
  '.woff2': 'font/woff2'
};

function sendJson(res, statusCode, data) {
  res.writeHead(statusCode, { 'Content-Type': 'application/json; charset=utf-8' });
  res.end(JSON.stringify(data));
}

function readJsonBodyAsync(req, maxBytes) {
  return new Promise((resolve, reject) => {
    readJsonBody(req, maxBytes, (err, data) => (err ? reject(err) : resolve(data)));
  });
}

function readJsonBody(req, maxBytes, callback) {
  let body = '';
  req.on('data', (chunk) => {
    body += chunk;
    if (body.length > maxBytes) req.destroy();
  });
  req.on('end', () => {
    try {
      callback(null, JSON.parse(body || '{}'));
    } catch (err) {
      callback(err);
    }
  });
}

function resolveProductPath(inputPath, expectedExt) {
  const targetPath = String(inputPath || '').split('?')[0].split('#')[0];
  if (!targetPath.toLowerCase().endsWith(expectedExt)) {
    throw new Error(`仅允许 ${expectedExt} 文件`);
  }
  const resolved = path.resolve(ROOT_DIR, '.' + targetPath);
  if (resolved !== PRODUCT_ROOT && !resolved.startsWith(PRODUCT_ROOT + path.sep)) {
    throw new Error('路径超出 product/ 允许范围');
  }
  return resolved;
}

/** Agent 只能改注册在配置里的产品入口目录内的文件 */
function resolveAgentWritablePath(inputPath, expectedExt) {
  const resolved = resolveProductPath(inputPath, expectedExt);
  const ok = AGENT_WRITE_ROOTS.some((root) => resolved === root || resolved.startsWith(root + path.sep));
  if (!ok) throw new Error('Agent 只能操作已注册产品的页面（见 proto-kit.config.json）');
  return resolved;
}

function findAgentWriteRoot(filePath) {
  return AGENT_WRITE_ROOTS.find((root) => filePath === root || filePath.startsWith(root + path.sep)) || '';
}

function captureProductFiles(rootDir) {
  const files = new Map();

  function walk(dir) {
    fs.readdirSync(dir, { withFileTypes: true }).forEach((entry) => {
      if (entry.name.startsWith('.')) return;
      const file = path.join(dir, entry.name);
      if (entry.isDirectory()) {
        walk(file);
        return;
      }
      if (!entry.isFile()) return;
      const stat = fs.statSync(file);
      const rel = path.relative(rootDir, file).split(path.sep).join('/');
      files.set(rel, `${stat.size}:${stat.mtimeMs}`);
    });
  }

  walk(rootDir);
  return files;
}

function startAgentTaskSnapshot(sessionID, htmlFile, htmlPath, prdPath) {
  const rootDir = findAgentWriteRoot(htmlFile);
  if (!rootDir) throw new Error('无法确定 Agent 任务所属产品目录');
  agentTaskSnapshots.set(sessionID, {
    rootDir,
    files: captureProductFiles(rootDir),
    context: {
      htmlPath: String(htmlPath || ''),
      prdPath: String(prdPath || '')
    },
    startedAt: Date.now()
  });

  if (agentTaskSnapshots.size > 50) {
    const oldest = [...agentTaskSnapshots.entries()]
      .sort((a, b) => a[1].startedAt - b[1].startedAt)
      .slice(0, agentTaskSnapshots.size - 50);
    oldest.forEach(([id]) => agentTaskSnapshots.delete(id));
  }
}

function consumeAgentTaskChanges(sessionID) {
  const snapshot = agentTaskSnapshots.get(sessionID);
  if (!snapshot) return { context: null, changes: [] };

  const current = captureProductFiles(snapshot.rootDir);
  const names = new Set([...snapshot.files.keys(), ...current.keys()]);
  const changes = [];
  names.forEach((name) => {
    const before = snapshot.files.get(name);
    const after = current.get(name);
    if (before === after) return;
    changes.push({
      file: path.relative(ROOT_DIR, path.join(snapshot.rootDir, name)).split(path.sep).join('/'),
      change: before === undefined ? 'created' : after === undefined ? 'deleted' : 'modified'
    });
  });
  agentTaskSnapshots.delete(sessionID);
  return { context: snapshot.context, changes };
}

function isLoopbackRequest(req) {
  const remoteAddress = String(req.socket.remoteAddress || '');
  return remoteAddress === '127.0.0.1' || remoteAddress === '::1' || remoteAddress === '::ffff:127.0.0.1';
}

/** 写入 / Agent 类接口一律只接受本机请求，即使服务器用 --host 0.0.0.0 对局域网开放预览 */
function requireLoopback(req, res) {
  if (isLoopbackRequest(req)) return true;
  sendJson(res, 403, { ok: false, error: '该接口仅允许从本机访问' });
  return false;
}

function handleLanAddress(req, res) {
  const requestUrl = new URL(req.url, 'http://localhost');
  const productId = String(requestUrl.searchParams.get('productId') || '').trim();
  const product = CONFIG.products.find((item) => item.id === productId);
  if (!product) return sendJson(res, 404, { ok: false, error: '未找到对应产品的局域网地址配置' });

  let surface = String(requestUrl.searchParams.get('surface') || '').trim();
  if (!surface && req.headers.referer) {
    try {
      const segments = new URL(req.headers.referer).pathname.split('/').filter(Boolean).map(decodeURIComponent);
      if (segments[0] === 'product' && segments[1] === productId) surface = segments[2] || '';
    } catch {}
  }

  return sendJson(res, 200, {
    ok: true,
    lanAddress: resolveLanAddress(product, surface)
  });
}

